// Package emails exposes the compiled Maizzle email templates as an embedded
// filesystem. The *.html files under dist/ are a build artifact: they are
// generated by `bun x vite build` (or `just build-assets`) from the Vue SFC
// sources in resources/js/emails/, and are gitignored.
//
// dist/ is a subdirectory (not embedded directly here) because Maizzle clears
// its entire output.path before every build — this file needs to live outside
// that directory to survive rebuilds.
package emails

import "embed"

// Files is embedded so the app renders the same HTML that Maizzle compiled.
// Run `bun x vite build` (or `bun x vite dev` for live preview) before
// `go build` so this embed sees up-to-date templates.
//
//go:embed dist/*.html
var Files embed.FS
